
const mongoose = require("mongoose");

const invoiceSchema = new mongoose.Schema(
  {
    // Unique invoice number generated by our backend.
    invoiceNumber: {
      type: String,
      required: [true, "Invoice number is required"],
      unique: true,
      trim: true,
    },

    // Customer receiving the invoice.
    user: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: [true, "Invoice customer is required"],
    },

    // Rental associated with this invoice.
    rental: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Rental",
      required: [true, "Invoice rental is required"],
      unique: true,
    },

    // Payment transaction associated with the invoice.
    transaction: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Transaction",
      default: null,
    },

    // Description of the charge.
    description: {
      type: String,
      required: [true, "Invoice description is required"],
      trim: true,
    },

    // Amount billed in kobo.
    amountKobo: {
      type: Number,
      required: true,
      min: [0, "Invoice amount cannot be negative"],
      validate: {
        validator: Number.isSafeInteger,
        message: "Invoice amount must be a whole number of kobo",
      },
    },

    currency: {
      type: String,
      enum: ["NGN"],
      default: "NGN",
    },

    // Billing status.
    status: {
      type: String,
      enum: ["unpaid", "paid", "cancelled", "refunded"],
      default: "unpaid",
    },

    // When payment was successfully completed.
    paidAt: {
      type: Date,
      default: null,
    },

    // When the invoice was issued.
    issuedAt: {
      type: Date,
      default: Date.now,
    },
  },
  {
    timestamps: true,
  }
);

const Invoice = mongoose.model("Invoice", invoiceSchema);

module.exports = Invoice;
